"use client";

import {useEffect,useRef,useState} from 'react';

import {hotelClient,hotelRpc,usd} from '@/lib/pilot';

import {signedCents} from '@/lib/service-forward';

import type {HandoffScope} from '@/lib/cashier-handoff';

import {readBankAccounts,readDepositCancellation,readDepositSources,prepareDepositRequest,depositArgs,readDepositReceipt,readDepositStatus,loadDeposit,saveDeposit,clearDeposit,type DepositRequest} from '@/lib/cashier-bank-deposits';

export function CashierBankDepositCreate({scope,onSaved}:{scope:HandoffScope;onSaved:()=>void}){

 const [accounts,setAccounts]=useState<ReturnType<typeof readBankAccounts>|null>(null),[cancelConfirmed,setCancelConfirmed]=useState(false),[sources,setSources]=useState<ReturnType<typeof readDepositSources>|null>(null),[selected,setSelected]=useState<Record<string,{value:string;available:string;earliest:string}>>({}),[pending,setPending]=useState<DepositRequest|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const alive=useRef(false),lock=useRef(false);

 useEffect(()=>{alive.current=true;try{setPending(loadDeposit(sessionStorage,scope))}catch(e){setError(e instanceof Error?e.message:'Unable to recover deposit.')}return()=>{alive.current=false}},[scope.tenant,scope.property,scope.actor]);

 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen deposits.');}

 async function load(next=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');try{await identify();if(!alive.current)return;const before=next?sources?.next:null;if(next&&!before)return;const value=await hotelRpc('cashier_bank_deposit_sources',{p_tenant:scope.tenant,p_property:scope.property,p_before:before??null});const parsed=readDepositSources(value,scope,before??null);const banks=next?accounts:readBankAccounts(await hotelRpc('cashier_bank_accounts',{p_tenant:scope.tenant,p_property:scope.property,p_before:null}),scope);await identify();if(alive.current){setSources(parsed);setAccounts(banks);if(!next)setSelected({})}}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to load received cash.')}finally{lock.current=false;if(alive.current)setBusy(false)}}

 async function save(request:DepositRequest,status=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;saveDeposit(sessionStorage,request);setPending(request);if(!status&&!request.account)throw Error('Check or cancel this older pending request before selecting a bank account.');const value=await hotelRpc(status?(request.account?'cashier_account_deposit_status':'cashier_bank_deposit_status'):'declare_cashier_account_deposit',status?{p_tenant:scope.tenant,p_property:scope.property,p_request:request.request}:depositArgs(request));await identify();if(!alive.current)return;if(status){if(!readDepositStatus(value,request)){setMessage('No saved deposit found. Retry the original request.');return}}else readDepositReceipt(value,request);clearDeposit(sessionStorage,request);setPending(null);setSelected({});setSources(null);setMessage('Deposit recorded. Bank reconciliation is still required.');onSaved()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Deposit interrupted. Check its saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}

 async function moreBanks(){if(lock.current||!accounts?.next)return;const before=accounts.next;lock.current=true;setBusy(true);setError('');try{await identify();if(!alive.current)return;const parsed=readBankAccounts(await hotelRpc('cashier_bank_accounts',{p_tenant:scope.tenant,p_property:scope.property,p_before:before}),scope,before);await identify();if(alive.current)setAccounts(parsed)}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to load bank accounts.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function cancel(){if(lock.current||!pending||!cancelConfirmed)return;const request=pending;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const value=await hotelRpc('cancel_cashier_bank_deposit_request',{p_tenant:scope.tenant,p_property:scope.property,p_request:request.request,p_confirmed:true});await identify();if(!alive.current)return;readDepositCancellation(value,request);clearDeposit(sessionStorage,request);setPending(null);setSelected({});setSources(null);setCancelConfirmed(false);setMessage('Unrecorded deposit cancelled. Delayed retries cannot create it.')}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Cancellation interrupted. Retry to confirm the result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section><h3>Record a deposit slip</h3>{pending?<><p>Pending deposit: {pending.reference}</p><button disabled={busy||!pending.account} onClick={()=>void save(pending)}>Retry deposit</button><button disabled={busy} onClick={()=>void save(pending,true)}>Check saved deposit</button><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this request only if no deposit was recorded.</label><button disabled={busy||!cancelConfirmed} onClick={()=>void cancel()}>Cancel unrecorded deposit</button></>:<><button disabled={busy} onClick={()=>void load()}>Choose received cash</button>{sources&&<><p>Select amounts from up to 100 sources. Refreshing sources clears your selection.</p>{sources.paused?<p>Cashier activity is paused.</p>:<><div>{sources.entries.map(s=><label className="field" key={s.id}>Cash source {s.id} — available {usd(Number(s.available))}<input aria-label={'Amount from '+s.id} inputMode="decimal" disabled={busy} value={selected[s.id]?.value??''} onChange={e=>setSelected(old=>{const copy={...old};if(e.target.value)copy[s.id]={value:e.target.value,available:s.available,earliest:s.earliest};else delete copy[s.id];return copy})}/></label>)}</div>{sources.next&&<button disabled={busy} onClick={()=>void load(true)}>More received cash</button>}<p>{Object.keys(selected).length} selected sources</p>{accounts?.entries.length===0&&<p>A manager must configure a bank account before recording deposits.</p>}{accounts?.next&&<button disabled={busy} onClick={()=>void moreBanks()}>More bank accounts</button>}<form onSubmit={e=>{e.preventDefault();try{const f=new FormData(e.currentTarget),date=String(f.get('date'));const allocations=Object.entries(selected).map(([handoff_id,s])=>{const cents=String(signedCents(s.value));if(BigInt(cents)<=BigInt(0)||BigInt(cents)>BigInt(s.available)||date<s.earliest||date>sources.today)throw Error('Review source amounts and deposit date.');return {handoff_id,amount_minor:cents}});const account=accounts?.entries.find(a=>a.id===f.get('bank'));if(!account)throw Error('Choose a configured bank account.');void save(prepareDepositRequest({scope,request:crypto.randomUUID(),account:account.id,bank:account.label,reference:String(f.get('reference')).trim(),date,reason:String(f.get('reason')).trim(),allocations}))}catch(e){setError(e instanceof Error?e.message:'Review deposit details.')}}}><fieldset disabled={busy||Object.keys(selected).length===0||!accounts?.entries.length}><label className="field">Bank account<select name="bank" required key={accounts?.entries[0]?.id}>{accounts?.entries.map(a=><option key={a.id} value={a.id}>{a.label} ({a.code})</option>)}</select></label><label className="field">Deposit slip reference<input name="reference" required minLength={2} maxLength={120}/></label><label className="field">Deposit date<input name="date" type="date" required max={sources.today} defaultValue={sources.today}/></label><label className="field">Deposit explanation<input name="reason" required minLength={4} maxLength={500}/></label><label><input type="checkbox" required/>I confirm the slip and cash amounts. This does not confirm bank receipt.</label><button>Record deposit</button></fieldset></form></>}</>}</>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>

}

